import glob
from collections import defaultdict

files = glob.glob("*.mafft")

# Parse all files to understand structure
org_counts = defaultdict(int)
file_seq_counts = {}

for f in sorted(files):
    seqs = {}
    current = None
    with open(f) as fh:
        for line in fh:
            line = line.strip()
            if line.startswith(">"):
                current = line[1:]
                seqs[current] = ""
            elif current:
                seqs[current] += line.replace("-", "")
    file_seq_counts[f] = len(seqs)
    for org in seqs:
        org_counts[org] += 1

print("Sequences per file (sample):")
for f, n in list(file_seq_counts.items())[:10]:
    print(f"  {f}: {n} sequences")

print(f"\nUnique organisms/taxa across all files:")
for org, count in sorted(org_counts.items()):
    print(f"  {org}: present in {count} files")

print(f"\nTotal files: {len(files)}")

